templates.template:
.sky-pinnedPosts
{
    margin: 8px 0 16px;

    .block-container
    {
        overflow: hidden;
        border-radius: @xf-borderRadiusMedium;
    }
}

.sky-pinnedPosts-header
{
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 12px 16px;
    border-bottom: 1px solid @xf-borderColor;

    .block-minorHeader
    {
        margin: 0;
        padding: 0;
        font-size: 13px;
        font-weight: 700;
        line-height: 1.35;
        letter-spacing: .02em;
    }
}

.sky-pinnedPosts-count
{
    flex: 0 0 auto;
    color: @xf-diminishedTextColor;
    font-size: 12px;
    font-weight: 600;
    white-space: nowrap;
}

.sky-pinnedPosts-body
{
    margin: 0;
    padding: 0;
}

.sky-pinnedPost
{
    display: flex;
    align-items: flex-start;
    gap: 10px;
    padding: 12px 16px;
    border-top: 1px solid @xf-borderColor;

    &:first-child
    {
        border-top: 0;
    }
}

.sky-pinnedPost-avatar
{
    flex: 0 0 auto;
}

.sky-pinnedPost-content
{
    flex: 1 1 auto;
    min-width: 0;
}

.sky-pinnedPost-meta
{
    display: flex;
    align-items: baseline;
    min-width: 0;
    color: @xf-diminishedTextColor;
    font-size: 12px;
    line-height: 1.4;
}

.sky-pinnedPost-label
{
	flex: 0 0 auto;
	max-width: 120px;
	overflow: hidden;
	margin-right: 6px;
	padding: 1px 6px;
	border: 1px solid @xf-borderColor;
	border-radius: @xf-borderRadiusSmall;
	color: @xf-diminishedTextColor;
	font-size: 10px;
	font-weight: 700;
	letter-spacing: .02em;
	line-height: 16px;
	text-overflow: ellipsis;
	text-transform: uppercase;
	white-space: nowrap;
}

.sky-pinnedPost-meta .username
{
	overflow: hidden;
    color: inherit;
    font-weight: 600;
    text-decoration: none;
    text-overflow: ellipsis;
    white-space: nowrap;

    &:hover
    {
        color: inherit;
        text-decoration: underline;
    }
}

.sky-pinnedPost-separator
{
    flex: 0 0 auto;
    margin: 0 5px;
}

.sky-pinnedPost-date
{
    flex: 0 1 auto;
    overflow: hidden;
    color: inherit;
    text-decoration: none;
    text-overflow: ellipsis;
    white-space: nowrap;

    &:hover
    {
        color: inherit;
        text-decoration: underline;
    }
}

.sky-pinnedPost-message
{
    display: -webkit-box;
    overflow: hidden;
    margin-top: 4px;
    color: @xf-textColor;
    font-size: 13px;
    line-height: 1.45;
    overflow-wrap: anywhere;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 4;

    > :first-child
    {
        margin-top: 0;
    }

    > :last-child
    {
        margin-bottom: 0;
    }

    img
    {
        max-width: 100%;
        height: auto;
    }
}

.sky-pinnedPost-footer
{
    margin-top: 5px;
    font-size: 12px;
}

.sky-pinnedPost-open
{
    color: @xf-linkColor;
    text-decoration: none;

    &:hover
    {
        text-decoration: underline;
    }
}

.sky-pinnedPost-actions
{
    display: flex;
    flex: 0 0 auto;
    align-items: center;
    gap: 2px;
    margin-left: 4px;
}

.sky-pinnedPost-actionForm
{
    margin: 0;
}

.sky-pinnedPost-action
{
    min-width: 28px;
    min-height: 28px;
    padding: 4px 7px;
    color: @xf-diminishedTextColor;
    font-size: 12px;
    line-height: 18px;

    &:hover
    {
        color: @xf-textColor;
        text-decoration: none;
    }
}

.sky-pinnedPost-unpin
{
	width: auto;
	margin-left: 2px;
}

.sky-pinnedPost-unpinIcon
{
	display: none;
}

.sky-pinnedPost-topMarker
{
	display: inline-flex;
	align-items: center;
	gap: 5px;
	margin: 0 0 8px;
	padding: 3px 7px;
	border-radius: @xf-borderRadiusSmall;
	font-size: 11px;
	font-weight: 700;
	line-height: 16px;
}

.sky-pinnedPosts-confirm .block-footer
{
    display: flex;
    justify-content: flex-end;
}

@media (max-width: 480px)
{
	.sky-pinnedPost
	{
		display: grid;
		grid-template-columns: 42px minmax(0, 1fr);
		grid-template-areas:
			"avatar content"
			". actions";
		column-gap: 10px;
		row-gap: 8px;
	}

	.sky-pinnedPost-avatar
	{
		grid-area: avatar;
	}

	.sky-pinnedPost-content
	{
		grid-area: content;
		min-width: 0;
	}

	.sky-pinnedPost-actions
	{
		grid-area: actions;
		width: auto;
		justify-content: flex-start;
		gap: 6px;
		margin: 0;
	}

	.sky-pinnedPost-action
	{
		min-width: 32px;
		min-height: 32px;
		padding: 6px 8px;
	}

	.sky-pinnedPost-unpin
	{
		width: 32px;
		min-width: 32px;
		margin-left: 0;
		padding: 4px;
		font-size: 18px;
		line-height: 20px;
	}

	.sky-pinnedPost-unpinText
	{
		display: none;
	}

	.sky-pinnedPost-unpinIcon
	{
		display: inline;
	}
}
